mapper.select:
select
mn.*,
od.Od_Name as odName,
od.Od_Type as odType,
od.Od_Source as odSource,
od.Od_Status as odStatus,
od.Od_Remark as odRemark,
od.Od_Address as odAddress,
od.Od_Method as odMethod,
od.Od_Body as odBody,
od.od_alias as odAlias
from Outline_Node_Datasource mn
left join Outline_Datasource od on od.id=mn.od_id

    
        and mn.Osl_Id=#{params.oslId}
    
    
        and mn.create_uid=#{params.createUname}
    
    
        and od.Od_Type=#{params.createUid}
    
    
        and od.Od_Source=#{params.odSource}
    
    
        and od.Od_Status=#{params.odStatus}
    
    
        and INSTR(mn.create_uname,#{params.createUname})
    
    
        and INSTR(od.Od_Name,#{params.odName})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC

select mn.*, od.Od_Name as odName, od.Od_Type as odType, od.Od_Source as odSource, od.Od_Status as odStatus, od.Od_Remark as odRemark, od.Od_Address as odAddress, od.Od_Method as odMethod, od.Od_Body as odBody, od.od_alias as odAlias, odt.T_Code as tCode from Outline_Node_Datasource mn left join Outline_Datasource od on od.id=mn.od_id left join Outline_Datasource_Temp odt on odt.Od_Id = od.id where mn.osl_id in
#{item}
order by mn.Create_Time DESC
